//! Mechanism/DATA tests only. No fabricated registered Root or Source owner.
use super::*;
fn scope()->UploadScope {UploadScope{version:2,home_id:"fixture".into(),workspace_id:"workspace".into(),transfer_id:uuid::Uuid::new_v4().to_string(),request_nonce:uuid::Uuid::new_v4().to_string(),mode:"image_batch_v1".into(),maximum_objects:100000,maximum_bytes:2147483648,maximum_object_bytes:4194304,
    constraint:super::super::super::OperationConstraint::image(super::super::super::ImagePreseedBudget::begin(std::time::Duration::from_secs(300)).unwrap().constraint()).unwrap(),manifest:Some(ObjectRef::from_bytes(rudder_engine::protocol::ObjectKind::Blob,b"fixture manifest")),maximum_manifest_bytes:Some(33554432)}}
fn batch()->BatchState{let s=scope();let refs=vec![ObjectRef::from_bytes(rudder_engine::protocol::ObjectKind::Blob,b"bytes")];header(&s,refs,0,uuid::Uuid::new_v4().to_string()).unwrap()}
fn a(b:&BatchState)->serde_json::Value{serde_json::json!({"format_version":1,"transfer_id":b.header.transfer_id,"request_nonce":b.header.request_nonce,"batch_id":b.header.batch_id,"ordinal":b.header.ordinal,"header_sha256":b.sha,"object_count":b.header.objects.len(),"total_bytes":b.header.total_bytes,"stored_bitmap":"01"})}
#[test]
fn image_batch_header_has_exact_canonical_bytes_and_hash(){let b=batch();assert_eq!(b.wire,canonical_json(&b.header).unwrap());assert_eq!(b.sha,hex(&Sha256::digest(&b.wire)));assert!(b.ack.is_none()&&b.unknown.is_none());assert!(b.wire.len()<=262144);}
#[test]
fn image_batch_header_refuses_duplicate_order_oversize_and_unnegotiated_scope(){let s=scope();let r=ObjectRef::from_bytes(rudder_engine::protocol::ObjectKind::Blob,b"a");assert!(header(&s,vec![r.clone(),r],0,uuid::Uuid::new_v4().to_string()).is_err());
    let mut s=s;let mut refs=vec![ObjectRef::from_bytes(rudder_engine::protocol::ObjectKind::Blob,b"b"),ObjectRef::from_bytes(rudder_engine::protocol::ObjectKind::Blob,b"a")];refs.sort_by_key(key);refs.reverse();assert!(header(&s,refs,0,uuid::Uuid::new_v4().to_string()).is_err());
    let mut large=s.manifest.clone().unwrap();large.size_bytes=4194305;assert!(header(&s,vec![large],0,uuid::Uuid::new_v4().to_string()).is_err());s.version=1;s.mode="image".into();assert!(header(&s,vec![s.manifest.clone().unwrap()],0,uuid::Uuid::new_v4().to_string()).is_err());}
#[test]
fn image_batch_ack_binds_original_identity_totals_and_canonical_bitmap(){let b=batch();ack(a(&b),&b).unwrap();for field in ["transfer_id","request_nonce","batch_id","header_sha256"]{let mut v=a(&b);v[field]=serde_json::json!("wrong");assert!(ack(v,&b).is_err());}
    for bitmap in ["", "1", "0A", "02", "0001", "xx"]{let mut v=a(&b);v["stored_bitmap"]=serde_json::json!(bitmap);assert!(ack(v,&b).is_err());}
    let mut v=a(&b);v["total_bytes"]=serde_json::json!(0);assert!(ack(v,&b).is_err());let mut v=a(&b);v["object_count"]=serde_json::json!(2);assert!(ack(v,&b).is_err());}
#[test]
fn image_batch_historical_reconciliation_is_unknown_data_and_never_ack(){let b=batch();let original=a(&b);let data=serde_json::json!({"type":"batch_unknown","format_version":1,"transfer_id":b.header.transfer_id,"request_nonce":b.header.request_nonce,"batch_id":b.header.batch_id,"header_sha256":b.sha,"reconciliation":{"format_version":1,"scope":"stored-original-image-batch-ack-data-only","ack":original}});unknown(&data,&b).unwrap();assert!(ack(data.clone(),&b).is_err());
    let mut wrong=data;wrong["reconciliation"]["ack"]["batch_id"]=serde_json::json!(uuid::Uuid::new_v4().to_string());assert!(unknown(&wrong,&b).is_err());}
#[test]
fn image_batch_unknown_counts_are_explicit_bounded_data(){let b=batch();let data=serde_json::json!({"format_version":1,"scope":"image-batch-unknown-data-only","transfer_id":b.header.transfer_id,"batch_id":b.header.batch_id,"header_sha256":b.sha,"actual_known_objects":null,"actual_unsettled_objects":1});reconciliation(&data,&b).unwrap();let mut missing=data.clone();missing.as_object_mut().unwrap().remove("actual_known_objects");assert!(reconciliation(&missing,&b).is_err());let mut too_many=data;too_many["actual_unsettled_objects"]=serde_json::json!(2);assert!(reconciliation(&too_many,&b).is_err());}
#[test]
fn image_batch_actual_stream_partial_write_keeps_original_pending_bytes(){let(mut sender,_receiver)=UnixStream::pair().unwrap();sender.set_nonblocking(true).unwrap();let size=4096i32;assert_eq!(unsafe{libc::setsockopt(sender.as_raw_fd(),libc::SOL_SOCKET,libc::SO_SNDBUF,(&size as *const i32).cast(),std::mem::size_of::<i32>() as libc::socklen_t)},0);
    let original=vec![0x57;16384];let mut pending=original.clone();let mut sent=0;assert!(!write_stream_step(&mut sender,&mut pending,&mut sent).unwrap());assert!(sent>0&&sent<original.len());let partial=sent;assert!(!write_stream_step(&mut sender,&mut pending,&mut sent).unwrap());assert_eq!(sent,partial);assert_eq!(pending,original,"EAGAIN keeps the SAME bytes/cursor; it never queues a replacement header");}
